function solve(f, g) {
  // Derajat polinom = indeks koefisien terakhir.
  const df = f.length - 1
  const dg = g.length - 1
  if (df < dg) return ['little-o', 'big-O'] // f tumbuh pasti lebih lambat dari g
  if (df > dg) return ['big-omega', 'little-omega'] // f tumbuh pasti lebih cepat dari g
  return ['big-O', 'theta', 'big-omega'] // derajat sama: sebanding
}
